package com.ebdf.controller;
import com.ebdf.dao.PortalDAO;import com.google.gson.*;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.util.*;
@WebServlet("/api/donor/dashboard") public class DonorDashboardServlet extends HttpServlet {
 private final PortalDAO dao=new PortalDAO();private final Gson gson=new Gson();
 private Integer user(HttpServletRequest q,HttpServletResponse p)throws IOException{HttpSession s=q.getSession(false);if(s==null||s.getAttribute("userId")==null){p.setStatus(401);p.getWriter().write("{\"message\":\"Please login first\"}");return null;}if(!"DONOR".equals(s.getAttribute("userRole"))){p.setStatus(403);p.getWriter().write("{\"message\":\"Donor access required\"}");return null;}return ((Number)s.getAttribute("userId")).intValue();}
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws IOException{p.setContentType("application/json");p.setCharacterEncoding("UTF-8");Integer id=user(q,p);if(id==null)return;try{p.getWriter().write(gson.toJson(dao.donorDashboard(id)));}catch(Exception e){getServletContext().log("donor dashboard failed",e);p.setStatus(500);p.getWriter().write("{\"message\":\"Unable to load donor dashboard\"}");}}
 protected void doPut(HttpServletRequest q,HttpServletResponse p)throws IOException{p.setContentType("application/json");p.setCharacterEncoding("UTF-8");Integer id=user(q,p);if(id==null)return;try{JsonObject b=gson.fromJson(q.getReader(),JsonObject.class);String v=b.get("availability").getAsString().toUpperCase(Locale.ROOT);if(!Set.of("AVAILABLE","UNAVAILABLE").contains(v)){p.setStatus(400);p.getWriter().write("{\"message\":\"Invalid availability\"}");return;}if(!dao.setDonorAvailabilityByUser(id,v)){p.setStatus(404);p.getWriter().write("{\"message\":\"Donor profile not found\"}");return;}p.getWriter().write(gson.toJson(Map.of("message","Availability updated","availability",v)));}catch(Exception e){p.setStatus(400);p.getWriter().write("{\"message\":\"Unable to update availability\"}");}}
}
